package com.fishfind.docapi.repo;

import java.time.LocalDateTime;

/**
 * One catch log ({@code dbo.catch_memo}) as an MCP write tool submits it. Every field but the ids may be
 * {@code null}: a catch logged from a news article carries only what the article states, and a {@code null}
 * here is stored as {@code NULL}, never as a default.
 *
 * @param id       the new memo's id (generated by the caller, so a retried call updates instead of duplicating)
 * @param lakeId   the water body ({@code dbo.lake.lake_id})
 * @param userId   the author: the account that owns the MCP key
 * @param fishId   resolved species ({@code dbo.fish.fish_id})
 * @param angler   who caught it, when that is not the author (a news report's angler)
 * @param released {@code true} released, {@code false} kept, {@code null} not stated
 * @param weather  air temperature, conditions and water temperature (1.30.0), never {@code null}
 */
public record CatchLog(String id, String lakeId, String userId, String fishId, String species, String angler, String title,
                       String text, Double lat, Double lon, String method, String tackle, String lure,
                       LocalDateTime catchDate, Double weight, String weightUnit, Double length, String lengthUnit,
                       Boolean released, boolean isPrivate, Weather weather) {

    /**
     * The weather columns of {@code dbo.catch_memo}, as the portal fills them: from the water body's station
     * forecast ({@code dbo.fn_catch_weather_snapshot}) unless the author overrides a value.
     *
     * @param temp     air temperature, °C
     * @param pressure air pressure, as the forecast gives it
     * @param text     conditions, e.g. {@code Clear}
     * @param icon     the forecast icon code for {@code text}, e.g. {@code 01d}; {@code null} for free text
     * @param water    water temperature, °C
     */
    public record Weather(Double temp, Double pressure, String text, String icon, Double water) {

        public static final Weather NONE = new Weather(null, null, null, null, null);

        /** True when no column is set, e.g. a water body with no station or a date with no forecast kept. */
        public boolean isEmpty() {
            return temp == null && pressure == null && text == null && icon == null && water == null;
        }
    }

    /** This log with {@code weather} instead of its own. */
    public CatchLog withWeather(Weather weather) {
        return new CatchLog(id, lakeId, userId, fishId, species, angler, title, text, lat, lon, method, tackle, lure,
                catchDate, weight, weightUnit, length, lengthUnit, released, isPrivate, weather);
    }
}
